<?php
namespace App\Services;use App\Collaboration\{CollaborationResourceReference,CollaborationResourceRegistry};use App\Models\{ResourceEditingSession,User};use Illuminate\Support\Facades\DB;
final class ResourceEditingSessionService{public const TTL_SECONDS=90;public function __construct(private CollaborationResourceRegistry $resources,private ResourceEditingPresenceRegistry $registry){}public function start(User $user,string $type,string $id):array{$this->resolve($user,$type,$id);$now=now();$lease=ResourceEditingSession::create(['user_id'=>$user->id,'resource_type'=>$type,'resource_id'=>$id,'started_at'=>$now,'last_heartbeat_at'=>$now,'expires_at'=>$now->copy()->addSeconds(self::TTL_SECONDS)]);return $this->payload($lease,$user);}public function heartbeat(User $user,string $type,string $id,string $token):array{$this->resolve($user,$type,$id);$lease=DB::transaction(function()use($user,$type,$id,$token){$lease=ResourceEditingSession::whereKey($token)->lockForUpdate()->firstOrFail();abort_unless($lease->user_id===$user->id&&$lease->resource_type===$type&&$lease->resource_id===(string)$id,404);$now=now();$lease->update(['last_heartbeat_at'=>$now,'expires_at'=>$now->copy()->addSeconds(self::TTL_SECONDS)]);return $lease;});return $this->payload($lease,$user);}public function release(User $user,string $type,string $id,string $token):void{$lease=ResourceEditingSession::whereKey($token)->firstOrFail();abort_unless($lease->user_id===$user->id&&$lease->resource_type===$type&&$lease->resource_id===(string)$id,404);$lease->delete();}public function active(User $user,string $type,string $id):array{$this->resolve($user,$type,$id);return $this->editors($type,$id,$user);}private function resolve(User $user,string $type,string $id):void{$this->registry->assertSupported($type);$this->resources->resolve($user,new CollaborationResourceReference($type,$id),'edit');}private function editors(string $type,string $id,User $viewer):array{return ResourceEditingSession::where(['resource_type'=>$type,'resource_id'=>$id])->where('expires_at','>',now())->with('user:id,name,status')->orderBy('started_at')->get()->map(fn($x)=>['sessionId'=>$x->user_id===$viewer->id?(string)$x->id:null,'user'=>['id'=>(string)$x->user_id,'displayName'=>$x->user?->name??'Former user','inactive'=>$x->user?->status!=='active'],'sameUser'=>$x->user_id===$viewer->id,'startedAt'=>$x->started_at->toISOString(),'expiresAt'=>$x->expires_at->toISOString()])->all();}private function payload(ResourceEditingSession $lease,User $user):array{return ['lease'=>['token'=>(string)$lease->id,'expiresAt'=>$lease->expires_at->toISOString(),'ttlSeconds'=>self::TTL_SECONDS],'editors'=>$this->editors($lease->resource_type,$lease->resource_id,$user)];}}
